# Continue an incoming trace
sentry_sdk.continue_trace(request.headers)
with sentry_sdk.start_span(name="handle-request"):
    ...

# Propagate to downstream services
traceparent = sentry_sdk.get_traceparent()
baggage = sentry_sdk.get_baggage()

# Start a fresh trace
sentry_sdk.new_trace()
with sentry_sdk.start_span(name="new-operation"):
    ...
```

### Filtering Configuration

```js {tabTitle:TypeScript}
Sentry.init({
  ignoreSpans: [
    // apply on span name
    'GET /about',
    'events.signal *',
    /api\/\d+/,
    // ignore health check GET requests
    {
      name: /healthz?/,
      attributes: {
        'http.method': 'GET',
      }
    },
    // ignore all GET requests to /api/
    // (i.e. span name doesn't matter)
    {
      attributes: {
        'http.method': /GET \/api\/.*/,
      }
    },
    // ignore all spans with name starting with /imprint-
    // if glob patterns are supported
    {
      name: '/imprint-*'
    }
  ]
})

// Note: The glob patterns used in the example serve an illustrative purpose.
// They are not supported in JavaScript.
