import Sentry

SentrySDK.start { options in
    options.dsn = "___PUBLIC_DSN___"
    options.attachScreenshot = true
    options.beforeCaptureScreenshot = { _ in
        // Prevent screenshots in certain views
        return !isSensitiveView()
    }
}
```

