    // Retrieve the current context.
    val context: Context = sentry.getContext()

    // Record a breadcrumb in the current context. By default the last 100 breadcrumbs are kept.
    context.recordBreadcrumb(BreadcrumbBuilder().setMessage("User made an action").build())

    // Set the user in the current context.
    context.setUser(UserBuilder().setEmail("hello@sentry.io").build())

    // This sends a simple event to Sentry.
    sentry.sendMessage("This is a test")
    try {
      unsafeMethod()
    } catch (e: Exception) {
      // This sends an exception event to Sentry.
      sentry.sendException(e)
    }
  }

  companion object {
    private var sentry: SentryClient? = null

    @JvmStatic
    fun main(args: Array<String>) {
      /*
       It is recommended that you use the DSN detection system, which
       will check the environment variable "SENTRY_DSN", the Java
       System Property "sentry.dsn", or the "sentry.properties" file
       in your classpath. This makes it easier to provide and adjust
       your DSN without needing to change your code. See the configuration
       page for more information.

       For example, using an environment variable

      export SENTRY_DSN="___PUBLIC_DSN___"
      */
      Sentry.init()

      // You can also manually provide the DSN to the ``init`` method.
      // Sentry.init("___PUBLIC_DSN___");

      /*
       It is possible to go around the static ``Sentry`` API, which means
       you are responsible for making the SentryClient instance available
       to your code.
      */
      sentry = SentryClientFactory.sentryClient()
      val myClass = MyClass()
      myClass.logWithStaticAPI()
      myClass.logWithInstanceAPI()
    }
  }
}
```

### Building More Complex Events

For more complex messages, you’ll need to build an `Event` with the `EventBuilder` class:

```java
import io.sentry.Sentry;
import io.sentry.event.Event;
import io.sentry.event.EventBuilder;
import io.sentry.event.interfaces.ExceptionInterface;

public class MyClass {
  public static void main(String... args) {
    Sentry.init();
  }

  void unsafeMethod() {
    throw new UnsupportedOperationException("You shouldn't call this!");
  }

  void logSimpleMessage() {
    // This sends an event to Sentry.
    EventBuilder eventBuilder = new EventBuilder()
        .withMessage("This is a test")
        .withLevel(Event.Level.INFO)
        .withLogger(MyClass.class.getName());

    // Note that the *unbuilt* EventBuilder instance is passed in so that
    // EventBuilderHelpers are run to add extra information to your event.
    Sentry.capture(eventBuilder);
  }

  void logException() {
    try {
      unsafeMethod();
    } catch (Exception e) {
      // This sends an exception event to Sentry.
      EventBuilder eventBuilder = new EventBuilder()
          .withMessage("Exception caught")
          .withLevel(Event.Level.ERROR)
          .withLogger(MyClass.class.getName())
          .withSentryInterface(new ExceptionInterface(e));

      // Note that the *unbuilt* EventBuilder instance is passed in so that
      // EventBuilderHelpers are run to add extra information to your event.
      Sentry.capture(eventBuilder);
    }
  }
}
```

```kotlin
import io.sentry.Sentry
import io.sentry.event.Event
import io.sentry.event.EventBuilder
import io.sentry.event.interfaces.ExceptionInterface

class MyClass {
  fun unsafeMethod() {
    throw UnsupportedOperationException("You shouldn't call this!")
  }

  fun logSimpleMessage() {
    // This sends an event to Sentry.
    val eventBuilder: EventBuilder = EventBuilder()
      .withMessage("This is a test")
      .withLevel(Event.Level.INFO)
      .withLogger(MyClass::class.java.name)

    // Note that the *unbuilt* EventBuilder instance is passed in so that
    // EventBuilderHelpers are run to add extra information to your event.
    Sentry.capture(eventBuilder)
  }

  fun logException() {
    try {
      unsafeMethod()
    } catch (e: Exception) {
      // This sends an exception event to Sentry.
      val eventBuilder: EventBuilder = EventBuilder()
        .withMessage("Exception caught")
        .withLevel(Event.Level.ERROR)
        .withLogger(MyClass::class.java.name)
        .withSentryInterface(ExceptionInterface(e))

      // Note that the *unbuilt* EventBuilder instance is passed in so that
      // EventBuilderHelpers are run to add extra information to your event.
      Sentry.capture(eventBuilder)
    }
  }

  companion object {
    @JvmStatic
    fun main(args: Array<String>) {
      Sentry.init()
    }
  }
}
```

### Automatically Enhancing Events

You can also implement an `EventBuilderHelper` that is able to automatically enhance outgoing events.

```java
import io.sentry.Sentry;
import io.sentry.SentryClient;
import io.sentry.event.EventBuilder;
import io.sentry.event.helper.EventBuilderHelper;

public class MyClass {
  public void myMethod() {
    SentryClient client = Sentry.getStoredClient();

    EventBuilderHelper myEventBuilderHelper = new EventBuilderHelper() {
      @Override
      public void helpBuildingEvent(EventBuilder eventBuilder) {
        eventBuilder.withMessage("Overwritten by myEventBuilderHelper!");
      }
    };

    // Add an ``EventBuilderHelper`` to the current client instance. Note that
    // this helper will process *all* future events.
    client.addBuilderHelper(myEventBuilderHelper);

    // Send an event to Sentry. During construction of the event the message
    // body will be overwritten by ``myEventBuilderHelper``.
    Sentry.capture("Hello, world!");
  }
}
```

```kotlin
import io.sentry.Sentry
import io.sentry.SentryClient
import io.sentry.event.EventBuilder
import io.sentry.event.helper.EventBuilderHelper

class MyClass {
  fun myMethod() {
    val client: SentryClient = Sentry.getStoredClient()
    val myEventBuilderHelper: EventBuilderHelper = object : EventBuilderHelper() {
      fun helpBuildingEvent(eventBuilder: EventBuilder) {
        eventBuilder.withMessage("Overwritten by myEventBuilderHelper!")
      }
    }

    // Add an ``EventBuilderHelper`` to the current client instance. Note that
    // this helper will process *all* future events.
    client.addBuilderHelper(myEventBuilderHelper)

    // Send an event to Sentry. During construction of the event the message
    // body will be overwritten by ``myEventBuilderHelper``.
    Sentry.capture("Hello, world!")
  }
}
```

---
title: Migrating Version 4.1 to 4.2
sidebar_order: 999
description: "Learn about migrating from version 4.1.0 to 4.2.0"
---

## Migrating from `io.sentry:sentry` `4.1.0` to `io.sentry:sentry` `4.2.0`

`operation` is now a required property of the `SentryTransaction` and `SentrySpan`. Whenever a transaction or span is started, the value for `operation` must be provided:

```java
Sentry.startTransaction("transaction-name", "operation-name");
```

### Spring

#### RestTemplate instrumentation

Simplified `RestTemplate` instrumentation does not involve anymore setting `UriTemplateHandler` using `SentrySpanClientHttpRequestInterceptor`.

Code snippet adding Sentry `RestTemplate` instrumentation changed from:

```java
@Bean
RestTemplate restTemplate(IHub hub) {
  RestTemplate restTemplate = new RestTemplate();
  SentrySpanClientHttpRequestInterceptor sentryRestTemplateInterceptor = new SentrySpanClientHttpRequestInterceptor(hub);
  UriTemplateHandler templateHandler = restTemplate.getUriTemplateHandler();
  restTemplate.setUriTemplateHandler(sentryRestTemplateInterceptor.createUriTemplateHandler(templateHandler));
  restTemplate.setInterceptors(Collections.singletonList(sentryRestTemplateInterceptor));
  return restTemplate;
}
```

into:

```java
@Bean
RestTemplate restTemplate(IHub hub) {
  RestTemplate restTemplate = new RestTemplate();
  SentrySpanClientHttpRequestInterceptor sentryRestTemplateInterceptor = new SentrySpanClientHttpRequestInterceptor(hub);
  restTemplate.setInterceptors(Collections.singletonList(sentryRestTemplateInterceptor));
  return restTemplate;
}
```

#### SentryExceptionResolver does not send handled errors by default

To prevent `SentryExceptionResolver` from sending errors that have been already captured by `@ExceptionHandlers`, we've changed the order for `SentryExceptionResolver` to `1`.

Old behavior can be brought back by setting `exceptionResolverOrder` property on `@EnableSentry`:

```java
@EnableSentry(exceptionResolverOrder = -2147483648)
class CustomConfiguration {
  ...
}
```

### Spring Boot

#### SentryExceptionResolver does not send handled errors by default

To prevent `SentryExceptionResolver` from sending errors that have been already captured by `@ExceptionHandlers`, we've changed the order for `SentryExceptionResolver` to `1`.

Old behavior can be brought back by setting a property `sentry.exception-resolver-order=-2147483648`

#### `@SentryTransaction` `operation` is now required

`@SentryTransaction` must have `operation` property provided.

```java
class MyComponent {

  @SentryTransaction(name = "transaction-name", operation = "operation-name")
  @Scheduled(fixedRate = 3 * 1000L)
  void execute() {
      ...
    }
}
```

